  "brand": {
    "on":      { "value": "0",    "type": "other" },
    "display": { "value": "none", "type": "other" },
    "logo":    { "value": "none", "type": "other" },
    "header": {
      "bg":        { "value": "transparent",  "type": "other" },
      "bg-strong": { "value": "transparent",  "type": "other" },
      "fg":        { "value": "currentColor", "type": "other" }
    },
